android.extraProguardRules:
# Nitro modules (VisionCamera, face detector, nitro-image): JNI-bound hybrid objects.
-keep class com.margelo.nitro.** { *; }
-keep class com.madebyevan.thumbhash.** { *; }
# ONNX Runtime: the native library looks up Java classes and fields via JNI.
-keep class ai.onnxruntime.** { *; }
# MapLibre (native SDK calls back into Java via JNI) and react-native-maps.
-keep class org.maplibre.** { *; }
-keep class com.rnmaps.** { *; }
# Reanimated / Worklets.
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
# Expo modules: module definitions and records are read by reflection.
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keep class * implements expo.modules.kotlin.records.Record { *; }
-keep enum * implements expo.modules.kotlin.types.Enumerable { *; }
-keepclassmembers class * { @expo.modules.kotlin.records.Field *; }
# Google ML Kit (barcode + face detection).
-keep class com.google.mlkit.** { *; }
-dontwarn com.google.mlkit.**
# Keep annotations/generics/inner-class metadata that reflection-based libraries read.
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
# Room: databases are instantiated by name (<Database>_Impl) via reflection.
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class * extends androidx.room.RoomDatabase
# WorkManager (expo-notifications, Firebase): WorkDatabase_Impl and its initializers.
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
-keepnames class androidx.work.impl.WorkDatabase
-keep class androidx.work.** { *; }
-keep class * extends androidx.work.ListenableWorker { <init>(...); }
-keep class * extends androidx.work.InputMerger { <init>(); }
# androidx.startup: InitializationProvider instantiates initializers from manifest metadata.
-keep class * implements androidx.startup.Initializer { <init>(); }
-keepnames class * implements androidx.startup.Initializer
# Firebase / ML Kit: component registrars are discovered from manifest metadata.
-keep class * implements com.google.firebase.components.ComponentRegistrar { <init>(); }
-keep class com.google.firebase.** { *; }
-dontwarn com.google.firebase.**
-keep class com.google.android.gms.internal.mlkit_vision_** { *; }
# expo-notifications (FCM service, task/notification handlers).
-keep class expo.modules.notifications.** { *; }
# Expo modules core: converters and module registry use Kotlin reflection.
-keep class expo.modules.kotlin.** { *; }
-keep class kotlin.Metadata { *; }
# CameraX (VisionCamera): the camera2 config provider is loaded by reflection.
-keep class androidx.camera.camera2.Camera2Config$DefaultProvider { *; }
-keep class androidx.camera.** { *; }
# React Native / fbjni: classes and members called from native code.
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keep @com.facebook.jni.annotations.DoNotStrip class *
-keepclassmembers class * { @com.facebook.jni.annotations.DoNotStrip *; }
-keep class com.facebook.jni.** { *; }
-keep class * extends com.facebook.jni.HybridClassBase { *; }
# MapLibre networking.
-dontwarn okhttp3.**
-dontwarn okio.**
